For Perform callout and pause step, Copado generates a Resume URL once you save the details. In Testsigma, go to Test Plans > Test Plan > Test Plan Settings, select Copado Test plan call back hook, paste the URL in the Resume URL textbox, and click Update. The test plan then runs with the pause behavior.

Jenkins

pipeline {
  agent any
  environment {
    TESTSIGMA_API_KEY = credentials('testsigma-api-key')
  }
  stages {
    stage('Testsigma') {
      steps {
        sh './run-testsigma.sh 4821'
      }
    }
  }
}

:::note[NOTE]
Do not paste the API key inline in the shell step. Store it as a Jenkins credential and reference it, or it will appear in the build console log.
:::
Click Save, then Build Now to trigger the test plan.
In Testsigma, open Test Plans to confirm the run has started.
In Jenkins, open the build and select Console Log to follow execution.
Open Run Results in Testsigma for the detailed report.

Shell script

}
function checkTestPlanRunStatus{
  $global:IS_TEST_RUN_COMPLETED=0
  for($i=0; $i -le $NO_OF_POLLS;$i++){
    get_status
    Write-Host "Execution Status before going for wait: $EXECUTION_STATUS ,Status_message:"($RUN_RESPONSE.message)
    if ($EXECUTION_STATUS -eq "STATUS_IN_PROGRESS"){
      Write-Host "Sleep/Wait for $SLEEP_TIME seconds before next poll....."
      sleep $SLEEP_TIME
    }else{
      $global:IS_TEST_RUN_COMPLETED=1
      Write-Host "Automated Tests Execution completed...`nTotal script execution time:$(($i)*$SLEEP_TIME/60) minutes"
      break
    }
  }
}

function saveFinalResponseToAFile{
  if ($IS_TEST_RUN_COMPLETED -eq 0){
      $global:LOG_CONTENT="Wait time exceeded specified maximum time(MAX_WAIT_TIME_FOR_SCRIPT_TO_EXIT). Please visit below URL for Test Plan Run status.$APP_URL"
     Write-Host "LogContent:$LOG_CONTENT nResponse content:"($RUN_RESPONSE | ConvertTo-Json -Compress)
